import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import { PageHeader, StickyScrollWithFilters } from 'components';
import { StickyNavigationTopOffsetProvider } from 'hooks';
import { StyledGridContainer, StyledHomeContainer } from 'shared/Styles';

import { PERFORMANCE_TOOL_PAGE_NAME } from '../../constants';
import { MarketShareV2Content } from '../Kpis/MarketShareV2/MarketShareV2';

const FILTER_VISIBLE_FIELDS: string[] = [
  'zone',
  'country',
  'waterfall_filter',
  'portfolios',
  'beer_price_segment',
  'brands',
  'sub_brands',
  'periods',
  'weight_type',
  'category',
];
/**
 * Market Share V2 page
 * This page is used to display the Market Share V2 page
 * Temporary page
 */

export const MarketShareV2: React.FC = () => {
  const { formatMessage } = useIntl();
  const pageTitle = useMemo(
    () =>
      formatMessage({
        id: 'ValueCreation.PerformanceTool.pageTitle.marketShare',
      }),
    [formatMessage],
  );
  const pageSubtitle = useMemo(
    () =>
      formatMessage({
        id: 'ValueCreation.PerformanceTool.market_share_v2.subtitle',
      }),
    [formatMessage],
  );

  return (
    <>
      <StickyScrollWithFilters
        filter={{
          pageName: PERFORMANCE_TOOL_PAGE_NAME,
          visibleFields: FILTER_VISIBLE_FIELDS,
        }}
        breadcrumbs={{
          pageList: [
            { href: '/value-creation', pageName: 'Value Creation' },
            {
              href: '/value-creation/performance-tool',
              pageName: 'Performance Tool',
            },
          ],
          showIcon: true,
        }}
        isResponsivePage
        dataTestId={'market-share-v2-navigation'}
      />

      <StickyNavigationTopOffsetProvider
        navigationTestId={'market-share-v2-navigation'}
      >
        <StyledGridContainer isResponsivePage>
          <StyledHomeContainer>
            <PageHeader
              title={pageTitle}
              subtitle={pageSubtitle}
              loading={false}
            />
            <MarketShareV2Content />
          </StyledHomeContainer>
        </StyledGridContainer>
      </StickyNavigationTopOffsetProvider>
    </>
  );
};
